guided.solution:
def validity(values, allowed):
    present = [v for v in values if v is not None]
    return round(sum(v in allowed for v in present) / len(present), 2)

print(validity(["paid", "PAID", None, "failed", "shipped"], {"paid", "refunded", "failed"}))

from datetime import datetime

def age_hours(updated_at, now):
    return round((now - updated_at).total_seconds() / 3600, 1)

now = datetime(2025, 3, 6, 12, 0)
print(age_hours(datetime(2025, 3, 5, 22, 0), now))
print(age_hours(datetime(2025, 3, 6, 8, 30), now))
